def copier_rapports_vers_visites(apps, schema_editor):
    """Convertit les rapports par cycle en fiches de visite (historique)."""
    Client = apps.get_model("clients", "Client")
    Visite = apps.get_model("clients", "Visite")
    today = datetime.date.today()
    for client in Client.objects.all():
        cycles = [
            (client.derniere_1ere_visite, client.rapport_inspecteurs_1,
             client.date_remise_inspecteurs_1, client.rapport_assistante_1),
            (client.derniere_2eme_visite, client.rapport_inspecteurs_2,
             client.date_remise_inspecteurs_2, client.rapport_assistante_2),
        ]
        for date_visite, insp, date_remise, assist in cycles:
            if date_visite and date_visite <= today:
                Visite.objects.get_or_create(
                    client=client,
                    date_visite=date_visite,
                    defaults={
                        "rapport_inspecteurs": insp,
                        "date_remise_inspecteurs": date_remise,
                        "rapport_assistante": assist,
                    },
                )


